/* From Uiverse.io by Cornerstone-04 - Tags: checkbox, circle */
.__UIV_SCOPE__ .check_container {
  position: relative;
}

.__UIV_SCOPE__ .checkbox {
  position: relative;
  top: 1px;
  width: 30px;
  height: 30px;
  border: 2px solid #212fab;
  border-radius: 50px;
  cursor: pointer;
  display: block;
  transition: all 0.3s linear;
}

.__UIV_SCOPE__ .checkbox::after {
  content: "";
  position: absolute;
  top: 25%;
  left: 20%;
  width: 6px;
  height: 12px;
  opacity: 0;
  transform: rotate(45deg) scale(0) translate(-50%, -50%);
  border-right: 4px solid #ffffff;
  border-bottom: 4px solid #ffffff;
  transition: all 0.3s linear;
}

.__UIV_SCOPE__ #checkbox:checked ~ .checkbox::after {
  opacity: 1 !important;
  transform: rotate(50deg) scale(1) translate(20%, -25%) !important;
}

.__UIV_SCOPE__ #checkbox:checked ~ .checkbox {
  background: #212fab;
  border: none;
}

.__UIV_SCOPE__ .hidden {
  display: none !important;
}
